"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[88231],{88231:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/storm-wind-and-blade.png\\"\\n          title=\\"질풍론도\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"박하\\"\\n          publishedDate=\\"2014-01-03\\"\\n          isbn=\\"9788965701866\\"\\n          rating=2.5\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n작품 초반 지능적 범죄자와의 두뇌 싸움이라는 스릴러로 진행되려 했으나, 예측 불가능한 코미디의 영역으로 옮겨진다.  \\n<br>\\n모든 책임을 떠맡은 어설픈 일반적인 무기력한 중년의 연구원이라는 <mark>미스 캐스팅</mark>은 다소 지루할 수 있는 사건에 희극적 긴장감의 장치로 사용한다.  \\n<br>\\n어설프고 형편없는 그의 수상한 행동은 주변 인물들의 의심을 사며 의도치 않은 위기를 끊임없이 자초하게 된다.  \\n이러한 상황 속에서 우연히 두 명의 유능한 조력자를 만나 사건을 해결해 나간다.  \\n<br>\\n단순한 해프닝으로 끝나 버린 허무한 결말은 이 작품 전체를 관통하는 ```희극적 아이러니```를 완성하는 장치인 것 같다."}')}}]);